begin;create temp table commerce_results(name text,ok boolean) on commit drop;grant all on commerce_results to authenticated,anon,service_role;
create function pg_temp.check_commerce(label text,who uuid,statement text,expected text,as_role text default 'authenticated') returns void language plpgsql as $$declare value text;begin begin perform set_config('request.jwt.claims',json_build_object('sub',who,'role',as_role,'aal','aal1')::text,true);execute format('set local role %I',as_role);execute statement into value;reset role;perform set_config('request.jwt.claims','',true);insert into commerce_results values(label,expected='ok' or value is not distinct from expected);exception when others then reset role;perform set_config('request.jwt.claims','',true);insert into commerce_results values(label,expected like 'error:%' and sqlerrm ilike '%'||substr(expected,7)||'%');end;end $$;
insert into auth.users(id,is_anonymous,aud,role,raw_user_meta_data) values ('00000000-0033-4000-8000-000000000001',true,'authenticated','authenticated','{"username":"zz_commerce_0"}'),('00000000-0033-4000-8000-000000000002',true,'authenticated','authenticated','{"username":"zz_commerce_1"}'),('00000000-0033-4000-8000-000000000003',true,'authenticated','authenticated','{"username":"zz_commerce_2"}');
update auth.users set is_anonymous=false where id in('00000000-0033-4000-8000-000000000001','00000000-0033-4000-8000-000000000002');update public.profiles set is_guest=false where id in('00000000-0033-4000-8000-000000000001','00000000-0033-4000-8000-000000000002');
insert into public.servers(id,name,owner_id) values ('00000000-0033-4000-8000-000000000011','zz_commerce_1','00000000-0033-4000-8000-000000000001'),('00000000-0033-4000-8000-000000000012','zz_commerce_2','00000000-0033-4000-8000-000000000001'),('00000000-0033-4000-8000-000000000013','zz_commerce_3','00000000-0033-4000-8000-000000000001'),('00000000-0033-4000-8000-000000000014','zz_commerce_4','00000000-0033-4000-8000-000000000001'),('00000000-0033-4000-8000-000000000015','zz_commerce_5','00000000-0033-4000-8000-000000000001');
