select pg_temp.check_commerce('incorrect currency cannot fulfil','00000000-0033-4000-8000-000000000001',$q$select private.billing_complete((select(value->>'id')::uuid from orders where key='top1'),'cs_live_fixture1',1299,'usd',true,'cus_fixture',null,'pi_fixture1')$q$,'error:payment mismatch','postgres');
