insert into orders values('sandbox',private.billing_reserve('00000000-0033-4000-8000-000000000001','boost','00000000-0033-4000-8000-000000000011',false,false));select private.billing_complete((select(value->>'id')::uuid from orders where key='sandbox'),'cs_test_sandbox',299,'eur',false,'cus_test',null,'pi_sandbox');
insert into commerce_results select 'sandbox never activates real promotion',(select count(*) from private.server_promotions where server_id='00000000-0033-4000-8000-000000000011')::text='0';

insert into orders values('test_pending',private.billing_reserve('00000000-0033-4000-8000-000000000001','boost','00000000-0033-4000-8000-000000000011',false,false));select private.billing_bind((select(value->>'id')::uuid from orders where key='test_pending'),'cs_test_pending');
insert into commerce_results select 'live reconciliation excludes test Checkout sessions',not exists(select 1 from jsonb_array_elements(private.billing_lookup('00000000-0033-4000-8000-000000000001',null,true)->'pending') p where p->>'session'='cs_test_pending');
