select private.billing_subscription((select(value->>'id')::uuid from orders where key='plus'),'sub_plus','cus_plus','active',now()+interval '2 months',false,102,'in_second','pi_second');select private.billing_subscription((select(value->>'id')::uuid from orders where key='plus'),'sub_plus','cus_plus','canceled',null,false,99,null,null);
