-- Delayed activation retains its verified receipt and inventory; no refund is created.
update public.server_directory set enabled=false where server_id='00000000-0033-4000-8000-000000000012';
select private.billing_complete((select(value->>'id')::uuid from orders where key='top2'),'cs_live_delayed',1299,'eur',true,'cus_delayed',null,'pi_delayed');
insert into commerce_results select 'paid receipt retained while activation is pending',exists(select 1 from private.billing_orders where payment_intent='pi_delayed' and state='processing' and paid_at is not null);
select private.billing_expire((select(value->>'id')::uuid from orders where key='top2'),'cs_live_delayed');
insert into commerce_results select 'paid processing order cannot expire',exists(select 1 from private.billing_orders where payment_intent='pi_delayed' and state='processing');
insert into commerce_results select 'pending activation reserves the real slot',(private.billing_catalog()->>'topAvailable')='1';
update public.server_directory set enabled=true where server_id='00000000-0033-4000-8000-000000000012';select private.billing_expire_benefits();
insert into commerce_results select 'retry activates once after listing is restored',exists(select 1 from private.billing_orders where payment_intent='pi_delayed' and state='paid') and exists(select 1 from private.server_promotions where server_id='00000000-0033-4000-8000-000000000012' and ends_at=now()+interval '14 days');
select private.billing_expire_benefits();
insert into commerce_results select 'repeated retry does not extend paid period',exists(select 1 from private.server_promotions where server_id='00000000-0033-4000-8000-000000000012' and ends_at=now()+interval '14 days');
