select private.billing_close('00000000-0033-4000-8000-000000000001');
select pg_temp.check_commerce('deletion locks new purchases','00000000-0033-4000-8000-000000000001',$q$select private.billing_reserve('00000000-0033-4000-8000-000000000001','boost','00000000-0033-4000-8000-000000000015',true,false)$q$,'error:account deletion pending','postgres');
update private.billing_subscriptions set paid_until=now()-interval '1 second' where user_id='00000000-0033-4000-8000-000000000002';select private.billing_expire_benefits();
insert into commerce_results select 'expired paid entitlement removed',(select plus_since is null and not supporter_wall from public.profiles where id='00000000-0033-4000-8000-000000000002')::text='true';
insert into commerce_results select 'expired supporter badge removed',(select count(*) from public.user_badges where user_id='00000000-0033-4000-8000-000000000002' and badge='supporter')::text='0';
select jsonb_build_object('passed',count(*)filter(where ok),'total',count(*),'failed',coalesce(jsonb_agg(name)filter(where not ok),'[]')) as result from commerce_results;rollback;